package com.securevault.service;
import com.securevault.entity.*; import com.securevault.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class PasswordRecoveryService{
 private final UserRepository users;private final PasswordResetTokenRepository tokens;private final PasswordEncoder pe;private final NotificationService notifications;private final PasswordHistoryService history;
 public PasswordRecoveryService(UserRepository u,PasswordResetTokenRepository t,PasswordEncoder p,NotificationService n,PasswordHistoryService h){users=u;tokens=t;pe=p;notifications=n;history=h;}
 public String request(String email){User u=users.findByEmail(email).orElse(null);if(u==null)return null;String token=UUID.randomUUID().toString().replace("-","");PasswordResetToken t=new PasswordResetToken();t.setToken(token);t.setUser(u);t.setExpiresAt(LocalDateTime.now().plusMinutes(15));tokens.save(t);notifications.create(u,"PASSWORD_RECOVERY","Password recovery requested","A password reset was requested for your account.");return token;}
 public void reset(String token,String password){if(password==null||password.length()<8)throw new RuntimeException("Password must be at least 8 characters");PasswordResetToken t=tokens.findByToken(token).orElseThrow(()->new RuntimeException("Invalid reset token"));if(t.isUsed()||t.getExpiresAt().isBefore(LocalDateTime.now()))throw new RuntimeException("Reset token expired or used");User u=t.getUser();if(history.wasRecentlyUsed(u,password))throw new RuntimeException("Password was recently used");String hash=pe.encode(password);history.record(u,hash);u.setPassword(hash);users.save(u);t.setUsed(true);tokens.save(t);notifications.create(u,"PASSWORD_RECOVERY","Password changed","Your SecureVault password was changed successfully.");}
}
